template:
{%- set result = value.get("result") -%}
{%- set applied = result is mapping -%}
{%- set restore = value.get("source") is none -%}
<div class="studio-push" data-studio-push data-studio-mode="view">
<h1 class="studio-push-title">{% if restore %}Restore {{ value.target }} to version {{ value.get("restore") }}{% else %}Push {{ value.source }} into {{ value.target }}{% endif %}</h1>
<dl class="studio-push-record">
<div><dt>Source</dt><dd data-studio-push-source>{% if restore %}None (a restore of version {{ value.get("restore") }}){% else %}{{ value.source }}{% endif %}</dd></div>
<div><dt>Target</dt><dd data-studio-push-target>{{ value.target }}</dd></div>
<div><dt>State</dt><dd data-studio-push-state>{{ value.state }}</dd></div>
<div><dt>Label</dt><dd data-studio-push-label>{{ value.get("label") or "None" }}</dd></div>
<div><dt>Result</dt><dd data-studio-push-result>{% if applied %}Version {{ result.get("version") }} of {{ value.target }}{% else %}Not applied yet{% endif %}</dd></div>
</dl>
{%- if not applied and not restore %}
<section class="studio-push-review" aria-label="What the push will change">
<h2 class="studio-push-review-title">What the push will change</h2>
{{ embed(api_url("ui-push-previews", value.source) ~ "?target=" ~ (value.target|urlencode), ["studio", "studio-push"]) }}
</section>
{{ embed(api_url("ui-push-previews", value.source) ~ "?target=" ~ (value.target|urlencode), ["studio", "studio-push-after"]) }}
{%- endif %}
</div>
